changeSet.sql:
ALTER TABLE actions RENAME COLUMN metadata TO availability;

UPDATE actions
SET guidance_url = availability->>'guidanceLink'
WHERE availability IS NOT NULL AND jsonb_exists(availability, 'guidanceLink');

UPDATE actions
SET availability = jsonb_build_object('type', availability->'availableAreaType')
WHERE availability IS NOT NULL
  AND jsonb_exists(availability, 'availableAreaType');
